internal sealed class StateApproximationS3QuantumAlgebraStateApproximationIrreducibleBoundedLiftDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Bounded lifts in irreducible representations", H("Bounded lifts in irreducible representations"), Blocks(
        Paragraph(Text("For a nontrivial C*-algebra A in Type u with PartialOrder A and StarOrderedRing A, and any irreducible star representation on a complete complex inner product space H in Type v, every self-adjoint operator T has a positive original-algebra bound L chosen before the vectors and accuracy. A common original self-adjoint e, of norm at most L, approximates T on any two specified vectors. The construction uses self-adjoint density and clips in A by continuous functional calculus, without injectivity, a norm bound on raw approximants, separability or a sequential restriction. The basic state and cyclic-vector definitions and the purity-to-irreducibility supplier results provide the representation interface. The original namespace and complete telescopes are retained. The bound is consumed by uniform_signed_original_square in UniformSignedSquare, whose common e controls the square at Omega and T(Omega). This C*-algebra result leaves general JB algebras and approximants in a possibly incomplete dense original E unresolved; it does not establish the further Jordan-algebra or PB Gram consequences.")),
        Describe.Lean(DescribeId.Create("statement4"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/IrreducibleBoundedLift.selfAdjoint_lift"),
            H("selfAdjoint_lift"), StatementSource.FromAuthor(Disp(Statement4())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Choose any original preimage a of b from membership in pi.range, and replace it by its real symmetrization one half times (a+star a). map_add and map_star show that its image is one half times (b+star b), which equals b by self-adjointness. The construction needs no faithful or injective representation."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement5"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/IrreducibleBoundedLift.bounded_strong_lift"),
            H("bounded_strong_lift"), StatementSource.FromAuthor(Disp(Statement5())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Set R=1+norm(T) before choosing vectors or accuracy and normalize B=T/R to a self-adjoint contraction. Its inverse Kaplansky value U satisfies f(U)=B by cfc_kaplanskyFun_cfc_kaplanskyFunInv. Irreducibility and closure_image_toPointwiseConvergenceCLM_inter_selfAdjoint, together with selfAdjoint_lift, put U in the strong closure of represented original self-adjoint elements. Along the resulting nontrivial neighborhood filter, tendsto_cfc_kaplanskyFun_apply and StarAlgHom.map_cfc make e=R cfc(f,a) approximate T strongly, while norm_cfc_kaplanskyFun_le bounds norm(e) in A by R. Intersecting the two eventual accuracy sets gives simultaneous approximation of x and y."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("gnsstatement1"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/IrreducibleBoundedLift.eq_smul_one_of_commute_of_cyclic"),
            H("eq_smul_one_of_commute_of_cyclic"), StatementSource.FromAuthor(Disp(GNSStatement1())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Move pi(b) from the first inner-product slot to pi(star b) in the second, commute T through that operator, and apply the proportional coefficient hypothesis at star b*a. Thus T and scalar multiplication by c have the same inner products against every cyclic-orbit vector. DenseRange.eq_of_inner_right identifies their values on the orbit, and Continuous.ext_on extends equality to all of H."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("gnsstatement2"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/IrreducibleBoundedLift.coeffFunctional_apply"),
            H("coeffFunctional_apply"), StatementSource.FromAuthor(Disp(GNSStatement2())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The continuous functional coeffFunctional is obtained by LinearMap.mkContinuous from the coefficient a mapped to inner(Omega,T(pi(a)Omega)). Evaluation retains that defining linear map, so the asserted identity is definitional. The continuity bound used in the definition is norm(Omega) squared times norm(T), using contractivity of pi."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("gnsstatement3"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/IrreducibleBoundedLift.coeffFunctional_star_mul"),
            H("coeffFunctional_star_mul"), StatementSource.FromAuthor(Disp(GNSStatement3())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Expand pi(star a*a) as pi(star a) composed with pi(a), and use the commutant hypothesis to move T past pi(star a). The identity map_star turns pi(star a) into the adjoint of pi(a); ContinuousLinearMap.adjoint_inner_right then transfers it to the first slot."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("gnsstatement5"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/IrreducibleBoundedLift.scalar_of_isSelfAdjoint_of_isPure"),
            H("scalar_of_isSelfAdjoint_of_isPure"), StatementSource.FromAuthor(Disp(GNSStatement5())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Choose r>0 with r norm(S) at most one half and set T=r S+one half times the identity. The operator norm estimate bounds every diagonal quadratic form between 0 and norm(v) squared, proving positivity of T and 1-T. By coeffFunctional_star_mul and ContinuousLinearMap.IsPositive.inner_nonneg_right, the coefficient functional of T is positive and dominated by omega. Purity makes it proportional to omega, eq_smul_one_of_commute_of_cyclic makes T scalar, and solving the affine relation makes S scalar."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("gnsstatement6"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/IrreducibleBoundedLift.isIrreducible_of_isPure"),
            H("isIrreducible_of_isPure"), StatementSource.FromAuthor(Disp(GNSStatement6())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Taking adjoints of the commutation relation shows that star T also commutes with the representation. Hence the self-adjoint operators T+star T and i(star T-T) commute as well. Apply scalar_of_isSelfAdjoint_of_isPure to each, then reconstruct T as one half times the sum of the first and i times the second."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("gnsstatement7"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/IrreducibleBoundedLift.gnsVonNeumann_eq_univ_of_isIrreducible"),
            H("gnsVonNeumann_eq_univ_of_isIrreducible"), StatementSource.FromAuthor(Disp(GNSStatement7())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Irreducibility identifies the centralizer of the representation's range with scalar multiples of 1; smul_one_mem_centralizer supplies the converse inclusion. Every bounded operator commutes with such scalars, so the centralizer of this centralizer is the entire operator space. This proves the full bicommutant equality, beyond a statement only about its center."))), DescribeRole.Theorem))));

